//! The mesh viewer's scene building over a synthetic install: mesh records generated by
//! `tessera_mesh::synth` and a setup encoded by `tessera-formats`, written into archives
//! by the synthetic archive writer of `tessera-dat`'s own tests (included by path), plus
//! appearance records encoded by `tessera-formats` and one surface record written from
//! its layout (`material.md` §4.1). No game data is involved. Shader records are
//! deliberately missing, so material resolution fails and the draws fall back to a plain
//! material; the material plans themselves are unit-tested in `scene.rs`.

#[path = "../../../crates/dat/tests/common/mod.rs"]
mod datkit;

use std::sync::Arc;
use std::time::Duration;

use tessera_assets::{
    AssetKey, AssetState, AssetStore, JobContext, PoolConfig, Priority, StoreConfig, WorkerPool,
};
use tessera_dat::{ArchiveSet, SetOptions};
use tessera_explorer::ExplorerError;
use tessera_explorer::data::DataContext;
use tessera_explorer::decoders::ContextSource;
use tessera_explorer::scene::{
    MAX_CHAIN, MAX_NOTES, MAX_PARTS, SceneDecoder, SceneLimits, SceneRequest, SceneSource,
    build_scene, build_scene_limited,
};
use tessera_formats::Did;
use tessera_formats::appearance::{
    AppearanceBlock, AppearanceEntry, AppearanceExtra, AppearancePart, AppearanceRecord,
    EXTRA_KIND_DID, MaterialGroup,
};
use tessera_formats::setup::{Setup, TAGFILE_MAGIC};
use tessera_mesh::synth::{LevelSpec, MeshSpec, SubmeshSpec};

const MESH: u32 = 0x0600_0001;
const SMALL: u32 = 0x0600_0002;
const BROKEN: u32 = 0x0600_0003;
const MISSING: u32 = 0x0600_0099;
const SETUP: u32 = 0x0400_0001;
const SETUP_SMALL: u32 = 0x0400_0002;
/// The first of 40 setups of two parts each.
const MANY_SETUPS: u32 = 0x0400_0100;
const APPEARANCE: u32 = 0x2000_0001;
const HOSTILE: u32 = 0x2000_0002;
/// The surface of `MESH`'s first submesh (`tessera_mesh::synth`: 0x31000000 + serial).
const SURFACE: u32 = 0x3100_0001;
const GROUP_KEY: u32 = 0x1000_0001;
const GROUP_MATERIAL: u32 = 0x3000_0009;

/// A surface record (`material.md` §4.1): DID, shader, binding key, materials, tail.
fn surface_bytes(did: u32, binding_key: u32, materials: &[u32]) -> Vec<u8> {
    let mut b = Vec::new();
    for w in [did, 0x2B00_0001, binding_key, materials.len() as u32]
        .into_iter()
        .chain(materials.iter().copied())
    {
        b.extend_from_slice(&w.to_le_bytes());
    }
    b.extend_from_slice(&1u16.to_le_bytes());
    b
}

fn block(
    variant: f32,
    parts: &[u32],
    extras: &[u32],
    groups: Vec<MaterialGroup>,
) -> AppearanceBlock {
    AppearanceBlock {
        variant,
        group_param: 0.0,
        groups,
        parts: parts
            .iter()
            .enumerate()
            .map(|(i, &m)| AppearancePart {
                part_param: 0.0,
                slot: 0x1000_0100 + i as u32,
                mesh: Did(m),
            })
            .collect(),
        extras: extras
            .iter()
            .map(|&d| AppearanceExtra {
                kind: EXTRA_KIND_DID,
                slot: 0x1000_0200,
                did: Did(d),
            })
            .collect(),
    }
}

fn appearance(did: u32, entries: Vec<AppearanceEntry>) -> Vec<u8> {
    let key_table = entries.iter().map(|e| (e.key, 0)).collect();
    AppearanceRecord {
        did: Did(did),
        section: 0,
        entries,
        key_table,
    }
    .to_bytes()
}

struct Install {
    _dir: datkit::TempDir,
    ctx: Arc<DataContext>,
}

/// Two submeshes, a detail level drawing both and a proxy level drawing a third.
fn mesh_bytes() -> Vec<u8> {
    let spec = MeshSpec {
        did: MESH,
        flags: 1,
        submeshes: vec![
            SubmeshSpec {
                format: 0x3000_0152,
                vertices: 30,
            },
            SubmeshSpec {
                format: 0x3001_0112,
                vertices: 12,
            },
            SubmeshSpec {
                format: 0x0000_0112,
                vertices: 8,
            },
        ],
        levels: vec![LevelSpec::detail(vec![0, 1]), LevelSpec::proxy(vec![2])],
        build_byte: true,
    };
    spec.build().unwrap().to_bytes().unwrap()
}

fn install() -> Install {
    let dir = datkit::TempDir::new("explorer-mesh");
    let mut m = datkit::Builder::new();
    m.stored(MESH, mesh_bytes());
    let mut small = MeshSpec::single(0x3000_0112, 6);
    small.did = SMALL;
    m.stored(SMALL, small.build().unwrap().to_bytes().unwrap());
    let mut broken = MeshSpec::single(0x3000_0112, 6);
    broken.did = BROKEN;
    let mut b = broken.build().unwrap().to_bytes().unwrap();
    b.truncate(b.len() / 2);
    m.stored(BROKEN, b);
    std::fs::write(dir.0.join("client_mesh.dat"), &m.build().bytes).unwrap();
    let setup = Setup {
        did: Did(SETUP),
        tagfile: TAGFILE_MAGIC.to_vec(),
        parts: vec![Did(MESH), Did(SMALL), Did(MISSING)],
        ..Setup::default()
    };
    let small_setup = Setup {
        did: Did(SETUP_SMALL),
        tagfile: TAGFILE_MAGIC.to_vec(),
        parts: vec![Did(SMALL)],
        ..Setup::default()
    };
    let group = MaterialGroup {
        shader: Did(0),
        material: Did(GROUP_MATERIAL),
        a: 2,
        binding_key: GROUP_KEY,
        g: 0.0,
    };
    // Entry 0x10000010: a dye block, then the base block with a repeated part mesh, a
    // material group whose key matches SURFACE, and extras (one repeated, one missing).
    // Entry 0x10000011: two blocks, neither the base look.
    let entries = vec![
        AppearanceEntry {
            key: 0x1000_0010,
            blocks: vec![
                block(0.01, &[], &[], Vec::new()),
                block(
                    1.0,
                    &[MESH, MESH, SMALL],
                    &[SETUP_SMALL, SETUP_SMALL, 0x0400_0077],
                    vec![group],
                ),
            ],
        },
        AppearanceEntry {
            key: 0x1000_0011,
            blocks: vec![
                block(0.02, &[SMALL], &[], Vec::new()),
                block(0.03, &[MESH], &[], Vec::new()),
            ],
        },
    ];
    // A hostile entry: thousands of extras cycling over many setups (more parts than a
    // scene draws) and missing ones.
    let extras: Vec<u32> = (0..6000u32)
        .map(|i| match i % 3 {
            0 => SETUP,
            1 => MANY_SETUPS + i % 40,
            _ => 0x0400_1000 + i,
        })
        .collect();
    let hostile = vec![AppearanceEntry {
        key: 0x1000_0020,
        blocks: vec![block(1.0, &[], &extras, Vec::new())],
    }];
    let mut g = datkit::Builder::new();
    g.stored(SETUP, setup.to_bytes().unwrap());
    g.stored(SETUP_SMALL, small_setup.to_bytes().unwrap());
    for i in 0..40 {
        let s = Setup {
            did: Did(MANY_SETUPS + i),
            tagfile: TAGFILE_MAGIC.to_vec(),
            parts: vec![Did(MESH), Did(SMALL)],
            ..Setup::default()
        };
        g.stored(MANY_SETUPS + i, s.to_bytes().unwrap());
    }
    g.stored(APPEARANCE, appearance(APPEARANCE, entries));
    g.stored(HOSTILE, appearance(HOSTILE, hostile));
    g.stored(SURFACE, surface_bytes(SURFACE, GROUP_KEY, &[0x3000_0005]));
    std::fs::write(dir.0.join("client_general.dat"), &g.build().bytes).unwrap();
    let set = Arc::new(ArchiveSet::open(&dir.0, SetOptions::default()).unwrap());
    let ctx = Arc::new(DataContext::from_set(dir.0.clone(), set, None));
    Install { _dir: dir, ctx }
}

#[test]
fn a_mesh_scene_with_levels() {
    let inst = install();
    let job = JobContext::detached();
    let p = build_scene(&inst.ctx, MESH, SceneRequest::default(), &job).unwrap();
    assert_eq!(p.source, SceneSource::Mesh);
    assert!(p.drawable());
    assert_eq!(p.parts.len(), 1);
    let part = &p.parts[0];
    assert!(part.error.is_none(), "{:?}", part.error);
    assert_eq!(part.levels.len(), 2);
    assert_eq!(
        (part.levels[0].kind.as_str(), part.levels[1].kind.as_str()),
        ("detail", "proxy")
    );
    assert_eq!(part.level, 0);
    assert_eq!(part.submeshes.len(), 2);
    assert_eq!(part.vertices, 42);
    // Surfaces are missing: each draw still has a (failed, plain) material.
    for s in &part.submeshes {
        let m = &p.materials[s.material.unwrap()];
        assert!(m.error.is_some());
        assert!(m.gpu.base.is_none());
    }
    assert_eq!(p.level_labels.len(), 2);
    assert!(p.textures.is_empty());
    let (lo, hi) = p.aabb.unwrap();
    assert!((0..3).all(|i| lo[i] <= hi[i]));
    assert!(p.sphere.1 > 0.0);

    // The proxy level, and a level beyond the last (clamped).
    for lod in [1u8, 200] {
        let r = SceneRequest {
            lod,
            ..SceneRequest::default()
        };
        let p = build_scene(&inst.ctx, MESH, r, &job).unwrap();
        assert_eq!(p.parts[0].level, 1);
        assert_eq!(p.parts[0].submeshes.len(), 1);
        assert_eq!(p.parts[0].submeshes[0].submesh, 2);
    }
    // Vertex colours on (opt-in): still drawable.
    let r = SceneRequest {
        vertex_colors: true,
        ..SceneRequest::default()
    };
    assert!(build_scene(&inst.ctx, MESH, r, &job).unwrap().drawable());
}

#[test]
fn a_setup_scene_with_a_missing_and_a_broken_part() {
    let inst = install();
    let job = JobContext::detached();
    let p = build_scene(&inst.ctx, SETUP, SceneRequest::default(), &job).unwrap();
    assert_eq!(p.source, SceneSource::Setup);
    assert_eq!(p.chain.len(), 1);
    assert_eq!(p.chain[0].did, SETUP);
    assert_eq!(p.parts.len(), 3);
    assert!(p.parts[0].prepared.is_some() && p.parts[1].prepared.is_some());
    assert!(p.parts[2].error.is_some(), "missing part reported");
    assert!(p.drawable());
    assert!(p.notes.iter().any(|n| n.contains("setup.md §7")));
    // Identity transforms (setup.md §7).
    for part in &p.parts {
        assert_eq!(part.transform[0], 1.0);
        assert_eq!(part.transform[12..15], [0.0, 0.0, 0.0]);
    }

    let broken = build_scene(&inst.ctx, BROKEN, SceneRequest::default(), &job).unwrap();
    assert!(!broken.drawable());
    assert!(broken.parts[0].error.is_some());
}

#[test]
fn records_without_geometry_are_refused() {
    let inst = install();
    let job = JobContext::detached();
    for did in [0x4100_0001, 0x2500_0001] {
        assert!(matches!(
            build_scene(&inst.ctx, did, SceneRequest::default(), &job),
            Err(ExplorerError::NotApplicable(_))
        ));
    }
    // Missing records of the geometry types fail cleanly.
    for did in [
        0x0400_0077,
        0x4700_0001,
        0x1F00_0001,
        0x2000_0099,
        0x7900_0001,
        0x3000_0001,
    ] {
        assert!(
            build_scene(&inst.ctx, did, SceneRequest::default(), &job).is_err(),
            "{did:#x}"
        );
    }
    // A surface record that is missing still gives a preview sphere with a failed
    // material.
    let p = build_scene(&inst.ctx, 0x3100_0001, SceneRequest::default(), &job).unwrap();
    assert!(p.drawable());
    assert!(p.materials[0].error.is_some());
}

#[test]
fn scenes_build_on_asset_workers() {
    let inst = install();
    let pool = WorkerPool::new(PoolConfig::default());
    let store = AssetStore::new(
        &pool,
        ContextSource,
        SceneDecoder(Arc::clone(&inst.ctx)),
        StoreConfig::default(),
    );
    let key = AssetKey::new(SETUP, SceneRequest::default().variant());
    match store
        .request(key, Priority::Immediate)
        .wait(Duration::from_secs(30))
    {
        AssetState::Ready(p) => {
            assert_eq!(p.parts.len(), 3);
            assert!(p.heap_bytes() > 0);
        }
        other => panic!("{}", other.name()),
    }
}

#[test]
fn an_appearance_entry_with_groups_extras_and_repeated_meshes() {
    let inst = install();
    let job = JobContext::detached();
    let p = build_scene(&inst.ctx, APPEARANCE, SceneRequest::default(), &job).unwrap();
    assert_eq!(p.source, SceneSource::Appearance);
    assert_eq!(p.choices.len(), 2);
    assert_eq!(p.choice, 0);
    // The base block's three parts, then the extra setup's part (once, though named
    // twice); the missing extra is a note.
    let meshes: Vec<u32> = p.parts.iter().map(|x| x.mesh).collect();
    assert_eq!(meshes, [MESH, MESH, SMALL, SMALL]);
    assert!(p.parts[0].caption.starts_with("slot"));
    assert!(p.parts[3].caption.starts_with("extra"));
    // Repeated meshes share one prepared mesh.
    let a = p.parts[0].prepared.as_ref().unwrap();
    let b = p.parts[1].prepared.as_ref().unwrap();
    assert!(Arc::ptr_eq(a, b));
    assert!(Arc::ptr_eq(
        p.parts[2].prepared.as_ref().unwrap(),
        p.parts[3].prepared.as_ref().unwrap()
    ));
    // Chain: the appearance, then the extra setup (once).
    let chain: Vec<u32> = p.chain.iter().map(|l| l.did).collect();
    assert_eq!(chain, [APPEARANCE, SETUP_SMALL]);
    assert!(
        p.notes
            .iter()
            .any(|n| n.contains("1 extra setups could not be resolved"))
    );
    assert!(
        p.notes
            .iter()
            .any(|n| n.contains("1 repeated extra setups"))
    );
    assert!(p.notes.iter().any(|n| n.contains("2 blocks")));
    // The group whose binding key matches SURFACE is layered onto that draw (its
    // resolution then fails on the missing shader record).
    let first = &p.parts[0].submeshes[0];
    assert_eq!(first.surface, Some(SURFACE));
    let m = &p.materials[first.material.unwrap()];
    assert!(m.title.contains("+"), "{}", m.title);
    assert!(m.title.contains(&format!("{:#010x}", GROUP_MATERIAL)) || m.title.contains("30000009"));
    assert!(m.error.is_some());
    // The second draw's surface has no record: no group, plain title.
    let second = &p.parts[0].submeshes[1];
    assert!(!p.materials[second.material.unwrap()].title.contains('+'));
    // Both MESH parts share their materials (same surface and layering).
    assert_eq!(
        p.parts[0].submeshes[0].material,
        p.parts[1].submeshes[0].material
    );

    // Entry 2: no base block; the first block is shown and the fallback is noted.
    let r = SceneRequest {
        choice: 1,
        ..SceneRequest::default()
    };
    let p = build_scene(&inst.ctx, APPEARANCE, r, &job).unwrap();
    assert_eq!(p.choice, 1);
    assert_eq!(p.parts.len(), 1);
    assert_eq!(p.parts[0].mesh, SMALL);
    assert!(p.notes.iter().any(|n| n.contains("none is the base look")));
    // A choice beyond the last is clamped.
    let r = SceneRequest {
        choice: 200,
        ..SceneRequest::default()
    };
    assert_eq!(
        build_scene(&inst.ctx, APPEARANCE, r, &job).unwrap().choice,
        1
    );
}

#[test]
fn a_hostile_appearance_stays_bounded() {
    // Regression: every extra setup was resolved, each added a chain link or a note,
    // and the inspector laid out tens of thousands of rows per frame.
    let inst = install();
    let job = JobContext::detached();
    let started = std::time::Instant::now();
    let p = build_scene(&inst.ctx, HOSTILE, SceneRequest::default(), &job).unwrap();
    assert!(p.parts.len() <= MAX_PARTS, "{}", p.parts.len());
    assert!(p.chain.len() <= MAX_CHAIN, "{}", p.chain.len());
    assert!(p.notes.len() <= MAX_NOTES, "{}", p.notes.len());
    assert!(
        p.notes
            .iter()
            .any(|n| n.contains("further extra setups were not resolved"))
    );
    assert_eq!(p.parts.len(), MAX_PARTS);
    assert!(p.notes.iter().any(|n| n.contains("could not be resolved")));
    // Only MESH and SMALL (and a missing mesh) are named: two prepared meshes.
    let distinct: std::collections::HashSet<_> = p
        .parts
        .iter()
        .filter_map(|x| x.prepared.as_ref().map(Arc::as_ptr))
        .collect();
    assert!(distinct.len() <= 2);
    assert!(started.elapsed() < Duration::from_secs(20));
}

#[test]
fn the_scene_geometry_budget_leaves_parts_out() {
    let inst = install();
    let job = JobContext::detached();
    // SETUP: MESH (42 vertices at level 0), SMALL (6), a missing part. A budget of 45
    // vertices takes MESH and refuses SMALL.
    let tight = SceneLimits {
        max_vertices: 45,
        ..SceneLimits::default()
    };
    let p = build_scene_limited(&inst.ctx, SETUP, SceneRequest::default(), &job, &tight).unwrap();
    assert!(p.parts[0].prepared.is_some());
    assert!(p.parts[1].prepared.is_none());
    assert!(
        p.parts[1]
            .error
            .as_deref()
            .is_some_and(|e| e.contains("budget")),
        "{:?}",
        p.parts[1].error
    );
    assert!(p.notes.iter().any(|n| n.contains("geometry budget")));
    // With the default budget everything is built.
    let p = build_scene(&inst.ctx, SETUP, SceneRequest::default(), &job).unwrap();
    assert!(p.parts[1].prepared.is_some());
    assert!(!p.notes.iter().any(|n| n.contains("geometry budget")));
}
